    for (int i = 0; i < numLines; i++) {
        indices[i] = i + rand() % (numLines - i);
    }
    for (int i = 0; i < numLines; i++) {
        int temp = code[indices[i]];
        code[indices[i]] = code[i];
        code[i] = temp;
    }
    free(indices);
}

int main() {
